defmodule Parser do
  def integer(value), do: String.to_integer(value)
end

files.lib/names.ex:
defmodule Names do
  def unique(values), do: Enum.sort(Enum.uniq(values))
end

files.lib/percent.ex:
defmodule Percent do
  def clamp(value), do: min(value, 100)
end

files.lib/users.ex:
defmodule Users do
  def find(users, email), do: Enum.find(users, &(&1.email == email))
end

files.lib/chunks.ex:
defmodule Chunks do
  def chunks(values, size), do: Enum.chunk_every(values, size)
end

